using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;

namespace NumSharp.Tests.Polynomial
{
    /// <summary>
    ///     The Vandermonde family's (plan U5) wholeness pass: the C# argument kinds the oracle corpus cannot spell — it is
    ///     generated by Python, so its arguments are Python values — replayed against what NumPy 2.4.2 does with the value each
    ///     kind stands for under the house boundary map (NDPolyNumber.cs): a typed C# array or <see cref="Memory{T}"/> is an
    ///     ndarray of its dtype; <c>List&lt;T&gt;</c>, LINQ, <c>System.Tuple</c>, <c>object[,]</c>, jagged and <c>NDArray[]</c>
    ///     arrays are Python sequences; <c>short</c> / <c>byte</c> / <c>char</c> degrees bind the int overload the way C#
    ///     overload resolution does. The pass also pinned two fixes, with NumPy's bytes: a <c>char</c> degree container reads
    ///     <c>numpy.uint16</c> in NumPy's len() text, and scalar points that stack into an OBJECT array (a Python int past
    ///     uint64 among them) are computed — NumPy's per-element <c>+ 0.0</c> hands each dimension its own number.
    /// </summary>
    [TestClass]
    public class PolynomialVanderArgumentKindsTests
    {
        /// <summary>The logical-C-order bytes of <paramref name="a"/> as lowercase hex (NumPy's <c>tobytes().hex()</c>).</summary>
        /// <param name="a">The array (any layout).</param>
        /// <returns>The hex text.</returns>
        private static string Hex(NDArray a)
        {
            using var c = np.ascontiguousarray(a);
            var bytes = new byte[c.size * c.dtypesize];
            unsafe
            {
                var p = (byte*)c.Storage.Address + c.Shape.offset * c.dtypesize;
                for (int i = 0; i < bytes.Length; i++) bytes[i] = p[i];
            }
            return Convert.ToHexString(bytes).ToLowerInvariant();
        }

        /// <summary>dtype, shape and bytes as one comparable string.</summary>
        /// <param name="a">The array.</param><returns>The signature.</returns>
        private static string Sig(NDArray a) => $"{a.dtype.name}({string.Join(",", a.shape)}) {Hex(a)}";

        /// <summary>Asserts dtype, shape, flags and every byte against a NumPy dump of the result.</summary>
        /// <param name="r">The result.</param><param name="dtype">NumPy's dtype name.</param><param name="shape">NumPy's shape.</param>
        /// <param name="hex">NumPy's <c>tobytes().hex()</c>.</param>
        private static void AssertNumPy(NDArray r, string dtype, long[] shape, string hex)
        {
            r.dtype.name.Should().Be(dtype);
            r.shape.Should().Equal(shape);
            // NumPy's reshape of the fresh outer product: a view, C- and F-contiguous (a single row).
            r.flags.owndata.Should().BeFalse();
            r.flags.c_contiguous.Should().BeTrue();
            r.flags.f_contiguous.Should().BeTrue();
            Hex(r).Should().Be(hex);
        }

        /// <summary>A NumPy error's type and verbatim text.</summary>
        /// <typeparam name="TException">The expected exception type.</typeparam>
        /// <param name="call">The call.</param><param name="text">NumPy's message (a prefix).</param>
        private static void Raises<TException>(Action call, string text) where TException : Exception
            => call.Should().Throw<TException>().Which.Message.Should().StartWith(text);

        /// <summary>The power-series module (<c>np.polynomial.polynomial</c>).</summary>
        private static PowerSeriesModule Poly => np.polynomial.polynomial;

        /// <summary>The Chebyshev module (<c>np.polynomial.chebyshev</c>).</summary>
        private static ChebyshevModule Cheb => np.polynomial.chebyshev;

        /// <summary>The Legendre module (<c>np.polynomial.legendre</c>).</summary>
        private static LegendreModule Leg => np.polynomial.legendre;

        /// <summary>The Hermite module (<c>np.polynomial.hermite</c>).</summary>
        private static HermiteModule Herm => np.polynomial.hermite;

        // =========================================================================================================
        //  Points
        // =========================================================================================================

        /// <summary>
        ///     A typed C# array, a multi-dimensional typed array and a <c>Memory&lt;T&gt;</c> / <c>ReadOnlyMemory&lt;T&gt;</c> of a
        ///     dtype are ndarrays of THAT dtype: the matrix is the NDArray input's, byte for byte, in its dtype (a float[] gives
        ///     float32, a Half[] float16, an int[] / ulong[] / bool[] float64 — NumPy's <c>x + 0.0</c>).
        /// </summary>
        [TestMethod]
        public void Points_TypedArraysAndMemory_AreNdarraysOfTheirDtype()
        {
            var cases = new (object Typed, NDArray Nd, string Dtype)[]
            {
                (new[] { 0.5, -1.5, 2.0 }, np.array(new[] { 0.5, -1.5, 2.0 }), "float64"),
                (new[] { 0.5f, -1.5f }, np.array(new[] { 0.5f, -1.5f }), "float32"),
                (new[] { (Half)0.5, (Half)(-1.5) }, np.array(new[] { (Half)0.5, (Half)(-1.5) }), "float16"),
                (new[] { new Complex(0.5, 1), new Complex(-1, 0) }, np.array(new[] { new Complex(0.5, 1), new Complex(-1, 0) }), "complex128"),
                (new[] { 3, -2 }, np.array(new[] { 3, -2 }), "float64"),
                (new[] { ulong.MaxValue, 1UL }, np.array(new[] { ulong.MaxValue, 1UL }), "float64"),
                (new[] { true, false }, np.array(new[] { true, false }), "float64"),
                (new byte[] { 200, 1 }, np.array(new byte[] { 200, 1 }), "float64"),
                (new[,] { { 0.5, 1.5 }, { 2.5, -3.5 } }, np.array(new[,] { { 0.5, 1.5 }, { 2.5, -3.5 } }), "float64"),
                (new Memory<float>(new[] { 0.25f, 4f }), np.array(new[] { 0.25f, 4f }), "float32"),
                (new ReadOnlyMemory<double>(new[] { 0.25, 4.0 }), np.array(new[] { 0.25, 4.0 }), "float64"),
            };
            foreach (var (typed, nd, dtype) in cases)
            {
                string want = Sig(Leg.legvander(nd, 3));
                Sig(Leg.legvander(typed, 3)).Should().Be(want, typed.GetType().Name);
                Leg.legvander(typed, 3).dtype.name.Should().Be(dtype, typed.GetType().Name);
                // As 2-D / 3-D points (every coordinate the same kind): the stack's dtype is the typed array's.
                Sig(Cheb.chebvander2d(typed, typed, new[] { 1, 2 })).Should().Be(Sig(Cheb.chebvander2d(nd, nd, new[] { 1, 2 })), typed.GetType().Name);
            }
        }

        /// <summary>
        ///     <c>List&lt;T&gt;</c>, LINQ, <c>ValueTuple</c>, <c>System.Tuple</c>, <c>object[,]</c> (a list of rows), jagged arrays and
        ///     <c>NDArray[]</c> are Python SEQUENCES, coerced by np.array's rules: a <c>List&lt;float&gt;</c>'s items are Python
        ///     floats (float64, as NumPy's list of floats), a <c>List&lt;Half&gt;</c>'s NumPy float16 scalars (float16), and
        ///     every other kind equals the <c>object[]</c> list of the same items.
        /// </summary>
        [TestMethod]
        public void Points_Sequences_AreListsCoercedByNpArray()
        {
            string List(params object[] items) => Sig(Herm.hermvander(items, 2));
            Sig(Herm.hermvander(new List<double> { 0.5, 1.5 }, 2)).Should().Be(List(0.5, 1.5));
            Sig(Herm.hermvander(new List<float> { 0.5f, 1.5f }, 2)).Should().Be(List(0.5, 1.5), "C# floats are Python floats: float64");
            Herm.hermvander(new List<Half> { (Half)0.5, (Half)1.5 }, 2).dtype.name.Should().Be("float16");
            Sig(Herm.hermvander(new object[] { 0.5, 1.5 }.Select(v => v), 2)).Should().Be(List(0.5, 1.5), "LINQ is a list");
            Sig(Herm.hermvander((0.5, 1.5), 2)).Should().Be(List(0.5, 1.5), "a ValueTuple is a tuple");
            Sig(Herm.hermvander(Tuple.Create(0.5, 1.5), 2)).Should().Be(List(0.5, 1.5), "a System.Tuple is a tuple");
            Sig(Herm.hermvander(new object[,] { { 1, 2 }, { 3, 4 } }, 2))
                .Should().Be(Sig(Herm.hermvander(new object[] { new object[] { 1, 2 }, new object[] { 3, 4 } }, 2)), "object[,] is a list of rows");
            Sig(Herm.hermvander(new[] { new[] { 0.5, 1.5 }, new[] { 2.5, 3.5 } }, 2))
                .Should().Be(Sig(Herm.hermvander(np.array(new[,] { { 0.5, 1.5 }, { 2.5, 3.5 } }), 2)), "a jagged array is a list of ndarrays");
            Sig(Herm.hermvander(new[] { NDArray.Scalar(0.5f), NDArray.Scalar(1.5f) }, 2)).Should().Be(Sig(Herm.hermvander(np.array(new[] { 0.5f, 1.5f }), 2)),
                "NDArray[] of 0-d float32 arrays stacks float32");
            // 2-D / 3-D points of mixed kinds stack exactly like the same values as lists.
            Sig(Poly.polyvander2d(new List<double> { 0.5, 1.5 }, (2.0, -1.0), new[] { 2, 1 }))
                .Should().Be(Sig(Poly.polyvander2d(new object[] { 0.5, 1.5 }, new object[] { 2.0, -1.0 }, new[] { 2, 1 })));
        }

        /// <summary>
        ///     A typed C# collection (<c>List&lt;T&gt;</c>, <c>HashSet&lt;T&gt;</c>, <c>Queue&lt;T&gt;</c>, LINQ) of a dtype is coerced from
        ///     its values in one pass (the shared np.array coercion's typed-collection path, added by this pass: item by item a
        ///     1000-point <c>List&lt;double&gt;</c> cost more than NumPy's whole call) — and must build exactly the array the item
        ///     walk builds from the same Python values spelled as <c>object[]</c> lists: NumPy's discovered dtypes (a
        ///     <c>ulong</c> list is int64, uint64 past int64, float64 for a mix of both — NumPy's
        ///     <c>np.array([2**64-1, 1])</c> is float64; a <c>List&lt;float&gt;</c> is float64; an EMPTY list float64 with no
        ///     dtype vote), shapes when nested, and the ragged texts.
        /// </summary>
        [TestMethod]
        public void TypedCollections_BuildTheArrayTheirPythonListsBuild()
        {
            string Run(Func<object> seq)
            {
                try
                {
                    using var a = PolySequence.ToArray(seq());
                    return Sig(a);
                }
                catch (Exception e)
                {
                    return $"{e.GetType().Name}: {e.Message}";
                }
            }
            ulong max = ulong.MaxValue;
            var cases = new (Func<object> Typed, Func<object> Python, string Dtype)[]
            {
                (() => new List<ulong> { max, 1 }, () => new object[] { max, 1UL }, "float64"),
                (() => new List<ulong> { max, max - 5 }, () => new object[] { max, max - 5 }, "uint64"),
                (() => new List<ulong> { 3, 1 }, () => new object[] { 3UL, 1UL }, "int64"),
                (() => new List<float> { 0.1f }, () => new object[] { (double)0.1f }, "float64"),
                (() => new List<int> { int.MinValue, 7 }, () => new object[] { (long)int.MinValue, 7L }, "int64"),
                (() => new List<bool> { true, false }, () => new object[] { true, false }, "bool"),
                (() => new List<Half> { (Half)0.5 }, () => new object[] { (Half)0.5 }, "float16"),
                (() => new List<Complex> { new(1, 2) }, () => new object[] { new Complex(1, 2) }, "complex128"),
                (() => new List<int>(), () => new object[0], "float64"),
                (() => new HashSet<double> { 1.5, 2.5 }, () => new object[] { 1.5, 2.5 }, "float64"),
                (() => new Queue<double>(new[] { 1.5, 2.5 }), () => new object[] { 1.5, 2.5 }, "float64"),
                (() => Enumerable.Range(0, 3).Select(i => i * 0.5), () => new object[] { 0.0, 0.5, 1.0 }, "float64"),
                (() => (new List<double> { 1, 2 }, new object[] { 3, 4 }), () => (new object[] { 1.0, 2.0 }, new object[] { 3, 4 }), "float64"),
                (() => new object[] { new List<ulong> { max }, new List<int> { -1 } }, () => new object[] { new object[] { max }, new object[] { -1 } }, "float64"),
                (() => new object[] { new List<double> { 1, 2 }, new List<double> { 3 } }, () => new object[] { new object[] { 1.0, 2.0 }, new object[] { 3.0 } }, null),
                (() => new object[] { new List<double>(), new List<double> { 1 } }, () => new object[] { new object[0], new object[] { 1.0 } }, null),
                (() => new object[] { 3.0, new List<double> { 1, 2 } }, () => new object[] { 3.0, new object[] { 1.0, 2.0 } }, null),
            };
            foreach (var (typed, python, dtype) in cases)
            {
                string t = Run(typed), p = Run(python);
                t.Should().Be(p);
                if (dtype is not null)
                    t.Should().StartWith(dtype + "(");
                else
                    t.Should().StartWith("ValueError: setting an array element with a sequence.");
            }
            // Through the facades: a List<double> of points is the object[] list's matrix.
            Sig(Leg.legvander(new List<double> { 0.5, -1.5 }, 3)).Should().Be(Sig(Leg.legvander(new object[] { 0.5, -1.5 }, 3)));
            Sig(Leg.legvander2d(new List<double> { 0.5 }, new List<int> { 2 }, new[] { 1, 1 }))
                .Should().Be(Sig(Leg.legvander2d(new object[] { 0.5 }, new object[] { 2 }, new[] { 1, 1 })));
        }

        // =========================================================================================================
        //  Degrees
        // =========================================================================================================

        /// <summary>
        ///     C# overload resolution binds a <c>short</c> / <c>byte</c> / <c>sbyte</c> / <c>ushort</c> / <c>char</c> degree to the
        ///     int overload and every other integer kind (<c>long</c>, <c>uint</c>, <c>ulong</c>, <see cref="BigInteger"/>,
        ///     <c>bool</c>) to the object one — all of them operator.index integers, all the same matrix; a char is NumPy's uint16
        ///     scalar (its code point).
        /// </summary>
        [TestMethod]
        public void Degree_IntegerKinds_BothOverloads_OneMatrix()
        {
            var x = np.array(new[] { 0.5, -1.25, 2.0 });
            string want = Sig(Cheb.chebvander(x, 3));
            Sig(Cheb.chebvander(x, (short)3)).Should().Be(want);
            Sig(Cheb.chebvander(x, (byte)3)).Should().Be(want);
            Sig(Cheb.chebvander(x, (sbyte)3)).Should().Be(want);
            Sig(Cheb.chebvander(x, (ushort)3)).Should().Be(want);
            Sig(Cheb.chebvander(x, '\u0003')).Should().Be(want);
            Sig(Cheb.chebvander(x, 3L)).Should().Be(want);
            Sig(Cheb.chebvander(x, 3u)).Should().Be(want);
            Sig(Cheb.chebvander(x, 3UL)).Should().Be(want);
            Sig(Cheb.chebvander(x, new BigInteger(3))).Should().Be(want);
            Sig(Cheb.chebvander(x, (object)NDArray.Scalar(3L))).Should().Be(want, "a 0-d integer array is an index");
            Sig(Cheb.chebvander(x, true)).Should().Be(Sig(Cheb.chebvander(x, 1)), "True is 1");
            Cheb.chebvander(x, 'a').shape.Should().Equal(new long[] { 3, 98 }, "'a' is np.uint16(97)");
        }

        /// <summary>
        ///     Every non-integer C# degree raises NumPy's <c>deg must be an integer, received {format(deg,'')}</c>: a C# float /
        ///     double is a Python float (<c>2.0</c>), a Half np.float16 (formatted through float(): <c>1000.0</c>, where its str
        ///     would be 1e+03), a Complex a Python complex, a string itself, null None, a typed array its str, a list its repr.
        /// </summary>
        [TestMethod]
        public void Degree_NonIntegerKinds_NumPysTexts()
        {
            var x = np.array(new[] { 0.5 });
            Raises<TypeError>(() => Poly.polyvander(x, 2.0), "deg must be an integer, received 2.0");
            Raises<TypeError>(() => Poly.polyvander(x, 0.1f), "deg must be an integer, received 0.10000000149011612");
            Raises<TypeError>(() => Poly.polyvander(x, (Half)1000), "deg must be an integer, received 1000.0");
            Raises<TypeError>(() => Poly.polyvander(x, new Complex(2, 0)), "deg must be an integer, received (2+0j)");
            Raises<TypeError>(() => Poly.polyvander(x, "2"), "deg must be an integer, received 2");
            Raises<TypeError>(() => Poly.polyvander(x, (object)null), "deg must be an integer, received None");
            Raises<TypeError>(() => Poly.polyvander(x, new[] { 2 }), "deg must be an integer, received [2]");
            Raises<TypeError>(() => Poly.polyvander(x, new List<int> { 2 }), "deg must be an integer, received [2]");
            Raises<TypeError>(() => Poly.polyvander(x, ValueTuple.Create(2)), "deg must be an integer, received (2,)");
            Raises<TypeError>(() => Poly.polyvander(x, (object)NDArray.Scalar(true)), "deg must be an integer, received True");
        }

        /// <summary>
        ///     vander2d / vander3d's degree CONTAINER in every C# kind: <c>int[]</c>, <c>long[]</c>, <c>List&lt;int&gt;</c>, a
        ///     <c>ValueTuple</c>, a <c>System.Tuple</c>, LINQ and an NDArray give one matrix; NumPy's texts for the rest — a
        ///     container of non-integers (a bool[] / double[] is an ndarray: <c>received True</c> / <c>received 1.0</c>; a str's
        ///     items are one-character strs), and a scalar with no len() (a char is np.uint16: <c>'numpy.uint16'</c>).
        /// </summary>
        [TestMethod]
        public void DegreeContainer_EveryCSharpKind()
        {
            var x = np.array(new[] { 0.5, -1.5 });
            var y = np.array(new[] { 2.0, 0.25 });
            string want = Sig(Leg.legvander2d(x, y, new object[] { 1, 2 }));
            Sig(Leg.legvander2d(x, y, new[] { 1, 2 })).Should().Be(want);
            Sig(Leg.legvander2d(x, y, new[] { 1L, 2L })).Should().Be(want);
            Sig(Leg.legvander2d(x, y, new List<int> { 1, 2 })).Should().Be(want);
            Sig(Leg.legvander2d(x, y, (1, 2))).Should().Be(want);
            Sig(Leg.legvander2d(x, y, Tuple.Create(1, 2))).Should().Be(want);
            Sig(Leg.legvander2d(x, y, Enumerable.Range(1, 2))).Should().Be(want);
            Sig(Leg.legvander2d(x, y, np.array(new[] { 1, 2 }))).Should().Be(want);
            Sig(Leg.legvander2d(x, y, new[] { NDArray.Scalar(1L), NDArray.Scalar(2L) })).Should().Be(want, "0-d integer arrays are indices");

            Raises<TypeError>(() => Leg.legvander2d(x, y, new[] { true, false }), "deg must be an integer, received True");
            Raises<TypeError>(() => Leg.legvander2d(x, y, new[] { 1.0, 2.0 }), "deg must be an integer, received 1.0");
            Raises<TypeError>(() => Leg.legvander2d(x, y, "12"), "deg must be an integer, received 1");
            Raises<TypeError>(() => Leg.legvander2d(x, y, new object[] { 1, 2.0 }), "deg must be an integer, received 2.0");
            Raises<TypeError>(() => Leg.legvander2d(x, y, '\u0002'), "object of type 'numpy.uint16' has no len()");
            Raises<TypeError>(() => Leg.legvander2d(x, y, 2), "object of type 'int' has no len()");
            Raises<TypeError>(() => Leg.legvander2d(x, y, 2.0), "object of type 'float' has no len()");
            Raises<TypeError>(() => Leg.legvander2d(x, y, (Half)2), "object of type 'numpy.float16' has no len()");
            Raises<TypeError>(() => Leg.legvander2d(x, y, true), "object of type 'bool' has no len()");
            Raises<TypeError>(() => Leg.legvander2d(x, y, null), "object of type 'NoneType' has no len()");
            Raises<TypeError>(() => Leg.legvander3d(x, y, x, NDArray.Scalar(2L)), "len() of unsized object");
            Raises<ValueError>(() => Leg.legvander3d(x, y, x, new List<int> { 1, 2 }), "Expected 3 dimensions of degrees, got 2");
        }

        // =========================================================================================================
        //  The object stack of scalars (NumPy 2.4.2 dumps; inputs spelled out in each call)
        // =========================================================================================================

        /// <summary>
        ///     Scalar points with a Python int past uint64 (C# <see cref="BigInteger"/>) stack into an OBJECT array in NumPy, and
        ///     its per-element <c>+ 0.0</c> gives each dimension its own number: <c>float(2**70)</c> (correctly rounded —
        ///     <c>2**64 + 2**11 + 1</c> rounds UP to <c>0x43f0000000000001</c>, where .NET's cast would truncate), a Python
        ///     float, a complex, an np.float16 (whose matrix is computed in float16, then promoted by the outer product) or a
        ///     0-d float32 array's np.float32. Results are NumPy's: dtype, the (1, R) view's flags and every byte.
        /// </summary>
        [TestMethod]
        public void ObjectStack_EachDimensionGetsItsOwnNumber()
        {
            var big = BigInteger.Pow(2, 70);
            // legvander2d(2**70, 1.5, [1, 2])
            AssertNumPy(Leg.legvander2d(big, 1.5, new[] { 1, 2 }), "float64", new long[] { 1, 6 },
                "000000000000f03f000000000000f83f0000000000000740000000000000504400000000000058440000000000006744");
            // legvander2d(2**70, np.float16(0.5), [1, 2]): the y matrix in float16, the product in float64
            AssertNumPy(Leg.legvander2d(big, (Half)0.5, new[] { 1, 2 }), "float64", new long[] { 1, 6 },
                "000000000000f03f000000000000e03f000000000000c0bf0000000000005044000000000000404400000000000020c4");
            // chebvander2d(2**70, 0.5-1j, [1, 1])
            AssertNumPy(Cheb.chebvander2d(big, new Complex(0.5, -1), new[] { 1, 1 }), "complex128", new long[] { 1, 4 },
                "000000000000f03f0000000000000000000000000000e03f000000000000f0bf00000000000050440000000000000000000000000000404400000000000050c4");
            // hermvander2d(2**64 + 2**11 + 1, 0.0, [1, 0]): float(int) rounds up
            AssertNumPy(Herm.hermvander2d(BigInteger.Pow(2, 64) + 2049, 0.0, new[] { 1, 0 }), "float64", new long[] { 1, 2 },
                "000000000000f03f0100000000000044");
            // chebvander3d(2**70, np.float16(0.5), np.array(1.5, np.float32), [1, 1, 2])
            AssertNumPy(Cheb.chebvander3d(big, (Half)0.5, NDArray.Scalar(1.5f), new[] { 1, 1, 2 }), "float64", new long[] { 1, 12 },
                "000000000000f03f000000000000f83f0000000000000c40000000000000e03f000000000000e83f000000000000fc3f"
                + "000000000000504400000000000058440000000000006c44000000000000404400000000000048440000000000005c44");
            // chebvander3d(np.float16(0.5), np.float16(0.25), 2**70, [2, 1, 1]): the first product in float16, then float64
            AssertNumPy(Cheb.chebvander3d((Half)0.5, (Half)0.25, big, new[] { 2, 1, 1 }), "float64", new long[] { 1, 12 },
                "000000000000f03f0000000000005044000000000000d03f0000000000003044000000000000e03f0000000000004044"
                + "000000000000c03f0000000000002044000000000000e0bf00000000000040c4000000000000c0bf00000000000020c4");
        }

        /// <summary>
        ///     The object stack's errors in NumPy's order: len(deg) first; then the per-element <c>+ 0.0</c> — an int past the
        ///     float range raises CPython's OverflowError (the half-way case <c>2**1024 - 2**970</c> rounds up to 2**1024), left
        ///     to right, so it beats a later None; a None element is refused (NumPy raises TypeError there; NumSharp has no object
        ///     dtype); and only then the per-dimension degree checks.
        /// </summary>
        [TestMethod]
        public void ObjectStack_ErrorsInNumPysOrder()
        {
            Raises<OverflowException>(() => Leg.legvander2d(BigInteger.Pow(2, 1024), 1.5, new[] { 1, 1 }), "int too large to convert to float");
            Raises<OverflowException>(() => Leg.legvander2d(BigInteger.Pow(2, 1024) - BigInteger.Pow(2, 970), 1.5, new[] { 1, 1 }),
                "int too large to convert to float");
            Leg.legvander2d(BigInteger.Pow(2, 1024) - BigInteger.Pow(2, 970) - 1, 1.5, new[] { 0, 0 }).GetDouble(0, 0).Should().Be(1.0,
                "just below the tie rounds down to the largest double");
            Raises<OverflowException>(() => Leg.legvander2d(BigInteger.Pow(2, 2000), null, new[] { 1, 1 }), "int too large to convert to float");
            Action noneFirst = () => Leg.legvander2d(null, BigInteger.Pow(2, 70), new[] { 1, 1 });
            noneFirst.Should().Throw<NotSupportedException>();
            Raises<ValueError>(() => Leg.legvander2d(BigInteger.Pow(2, 70), 1.5, new[] { 1, -1 }), "deg must be non-negative");
            Raises<TypeError>(() => Leg.legvander2d(BigInteger.Pow(2, 2000), 1.5, 3), "object of type 'int' has no len()");
            // Non-scalar points holding such an int: NumPy computes the matrices as Python-object arrays — refused.
            Action objectMatrix = () => Leg.legvander2d(new object[] { BigInteger.Pow(2, 70) }, new object[] { 1 }, new[] { 1, 1 });
            objectMatrix.Should().Throw<NotSupportedException>();
        }
    }
}
